PAYLOAD_EOF

echo "=== [2/6] Verifying node dependencies ==="
npm install --no-audit --prefer-offline 2>/dev/null || npm install

echo "=== [3/6] Building production frontend assets ==="
npm run build

echo "=== [4/6] Updating Nginx configuration ==="
if [ -d /etc/nginx/conf.d ]; then
  if [ -f deploy/nginx.conf ]; then
    cp deploy/nginx.conf /etc/nginx/conf.d/pay.gnbmentor.com.conf
    nginx -t 2>/dev/null && systemctl reload nginx 2>/dev/null || echo "Note: Nginx reload skipped (run manually if needed)"
  fi
fi

echo "=== [5/6] Restarting PM2 process ==="
pm2 restart gnbmentor-pay || pm2 start deploy/ecosystem.config.cjs --env production
pm2 save

echo "=== [6/6] Verifying live API endpoints on localhost:3000 ==="
sleep 2
echo -n "1. Health check: "
curl -s http://127.0.0.1:3000/api/health | head -c 120
echo ""
echo -n "2. Domain Search (.store @ $1.47 / PKR 412): "
curl -s "http://127.0.0.1:3000/api/domains/search?domain=gnbtest.store"
echo ""

echo "=========================================================="
echo " SUCCESS: pay.gnbmentor.com is up to date and live!"
echo "=========================================================="
